package pool

import (
	"context"
	"runtime"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func jobsOf(count int, fn func(ctx context.Context) error) chan Job {
	jobs := make(chan Job, count)
	for i := 0; i < count; i++ {
		jobs <- Job{ID: i, Run: fn}
	}
	close(jobs)
	return jobs
}

func drain(ch <-chan Result) int {
	count := 0
	for range ch {
		count++
	}
	return count
}

func TestConcurrencyLimit(t *testing.T) {
	var running, peak int32
	const workers = 3
	jobs := jobsOf(60, func(ctx context.Context) error {
		current := atomic.AddInt32(&running, 1)
		for {
			old := atomic.LoadInt32(&peak)
			if current <= old || atomic.CompareAndSwapInt32(&peak, old, current) {
				break
			}
		}
		time.Sleep(time.Millisecond)
		atomic.AddInt32(&running, -1)
		return nil
	})
	if got := drain(Process(context.Background(), jobs, workers)); got != 60 {
		t.Fatalf("expected 60 results, got %d", got)
	}
	if peak > workers {
		t.Fatalf("peak concurrency %d exceeds workers %d", peak, workers)
	}
}

func TestAtMostOnce(t *testing.T) {
	var calls int32
	var mu sync.Mutex
	seen := map[int]int{}
	jobs := jobsOf(100, func(ctx context.Context) error {
		atomic.AddInt32(&calls, 1)
		return nil
	})
	for result := range Process(context.Background(), jobs, 5) {
		mu.Lock()
		seen[result.ID]++
		mu.Unlock()
	}
	if atomic.LoadInt32(&calls) != 100 {
		t.Fatalf("expected 100 calls, got %d", calls)
	}
	for id, count := range seen {
		if count != 1 {
			t.Fatalf("job %d handled %d times", id, count)
		}
	}
}

func TestOutputCloses(t *testing.T) {
	jobs := jobsOf(10, func(ctx context.Context) error { return nil })
	done := make(chan int, 1)
	go func() { done <- drain(Process(context.Background(), jobs, 2)) }()
	select {
	case count := <-done:
		if count != 10 {
			t.Fatalf("expected 10 results, got %d", count)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("output channel never closed")
	}
}

func TestNoNewJobsAfterCancel(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	var startedAfterCancel int32
	var cancelled int32
	var started int32
	jobs := make(chan Job, 200)
	for i := 0; i < 200; i++ {
		jobs <- Job{ID: i, Run: func(ctx context.Context) error {
			if atomic.LoadInt32(&cancelled) == 1 {
				atomic.AddInt32(&startedAfterCancel, 1)
			}
			atomic.AddInt32(&started, 1)
			time.Sleep(time.Millisecond)
			return nil
		}}
	}
	close(jobs)

	out := Process(ctx, jobs, 4)
	for i := 0; i < 4; i++ {
		if _, ok := <-out; !ok {
			break
		}
	}
	atomic.StoreInt32(&cancelled, 1)
	cancel()
	deadline := time.After(10 * time.Second)
	for {
		select {
		case _, ok := <-out:
			if !ok {
				if startedAfterCancel > 4 {
					t.Fatalf("jobs started after cancellation: %d", startedAfterCancel)
				}
				return
			}
		case <-deadline:
			t.Fatal("output channel did not close after cancellation")
		}
	}
}

func TestInflightContextCancelled(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	inside := make(chan struct{}, 1)
	sawCancel := make(chan struct{}, 1)
	jobs := make(chan Job, 1)
	jobs <- Job{ID: 1, Run: func(ctx context.Context) error {
		inside <- struct{}{}
		<-ctx.Done()
		sawCancel <- struct{}{}
		return ctx.Err()
	}}
	close(jobs)

	out := Process(ctx, jobs, 1)
	<-inside
	cancel()
	select {
	case <-sawCancel:
	case <-time.After(5 * time.Second):
		t.Fatal("in-flight Run did not receive the cancelled context")
	}
	select {
	case <-out:
	case <-time.After(5 * time.Second):
		t.Fatal("Process did not return a result after the in-flight job finished")
	}
}

func TestNoHangWhenConsumerStops(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	jobs := make(chan Job, 50)
	for i := 0; i < 50; i++ {
		jobs <- Job{ID: i, Run: func(ctx context.Context) error { time.Sleep(time.Millisecond); return nil }}
	}
	close(jobs)

	_ = Process(ctx, jobs, 3)
	cancel()
	time.Sleep(200 * time.Millisecond)
	// The test passes when the process is still able to run: no producer
	// goroutine may be blocked forever on an unread output channel.
	done := make(chan struct{})
	go func() { time.Sleep(50 * time.Millisecond); close(done) }()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("test process is stuck")
	}
}

func TestNonPositiveWorkers(t *testing.T) {
	for _, workers := range []int{0, -1} {
		jobs := jobsOf(3, func(ctx context.Context) error { return nil })
		out := Process(context.Background(), jobs, workers)
		count := 0
		deadline := time.After(5 * time.Second)
		for {
			select {
			case _, ok := <-out:
				if !ok {
					count = -1
					goto finished
				}
				count++
			case <-deadline:
				t.Fatalf("workers=%d: output channel never closed", workers)
			}
		}
	finished:
		if count > 0 {
			t.Fatalf("workers=%d: expected no results, got %d", workers, count)
		}
	}
}

func TestEmptyInputCloses(t *testing.T) {
	jobs := make(chan Job)
	close(jobs)
	out := Process(context.Background(), jobs, 3)
	select {
	case _, ok := <-out:
		if ok {
			t.Fatal("expected no results for empty input")
		}
	case <-time.After(5 * time.Second):
		t.Fatal("empty input did not close the output channel")
	}
}

func TestNoGoroutinePerJob(t *testing.T) {
	baseline := runtime.NumGoroutine()
	release := make(chan struct{})
	jobs := make(chan Job, 500)
	for i := 0; i < 500; i++ {
		jobs <- Job{ID: i, Run: func(ctx context.Context) error {
			<-release
			return nil
		}}
	}
	close(jobs)

	out := Process(context.Background(), jobs, 2)
	time.Sleep(100 * time.Millisecond)
	peak := runtime.NumGoroutine()
	close(release)
	drain(out)
	if peak-baseline > 20 {
		t.Fatalf("goroutine count grew by %d with 2 workers and 500 jobs", peak-baseline)
	}
}

func TestNoLeakAfterCompletion(t *testing.T) {
	baseline := runtime.NumGoroutine()
	for iteration := 0; iteration < 5; iteration++ {
		jobs := jobsOf(40, func(ctx context.Context) error { return nil })
		drain(Process(context.Background(), jobs, 3))
	}
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		runtime.GC()
		if runtime.NumGoroutine() <= baseline+2 {
			return
		}
		time.Sleep(50 * time.Millisecond)
	}
	t.Fatalf("goroutine leak: baseline %d, now %d", baseline, runtime.NumGoroutine())
}

"""Hidden acceptance tests for pipeline.window.last_values (not shown to the model)."""

import unittest

from pipeline.window import last_values


class BoundaryTests(unittest.TestCase):
    def test_returns_exactly_count_values(self) -> None:
        self.assertEqual(last_values([1, 2, 3, 4, 5], 2), [4, 5])
        self.assertEqual(last_values([1, 2, 3, 4, 5], 3), [3, 4, 5])
        self.assertEqual(last_values([1, 2, 3, 4, 5], 4), [2, 3, 4, 5])

    def test_count_one_returns_the_last_value(self) -> None:
        self.assertEqual(last_values([7, 8, 9], 1), [9])

    def test_count_above_length_keeps_everything(self) -> None:
        self.assertEqual(last_values([1, 2, 3], 10), [1, 2, 3])

    def test_non_positive_count_is_empty(self) -> None:
        self.assertEqual(last_values([1, 2, 3], 0), [])
        self.assertEqual(last_values([1, 2, 3], -1), [])

    def test_empty_input_is_empty(self) -> None:
        self.assertEqual(last_values([], 5), [])

    def test_duplicates_are_kept(self) -> None:
        self.assertEqual(last_values([5, 5, 5, 5], 2), [5, 5])

    def test_input_is_not_mutated(self) -> None:
        values = [1, 2, 3]
        last_values(values, 2)
        self.assertEqual(values, [1, 2, 3])


if __name__ == "__main__":
    unittest.main()

"""Hidden acceptance tests for sink.paths.join_path (not shown to the model)."""

import unittest

from sink.paths import join_path


class CacheTests(unittest.TestCase):
    def test_same_name_under_different_roots(self) -> None:
        self.assertEqual(join_path("/srv/a", "part-1.csv"), "/srv/a/part-1.csv")
        self.assertEqual(join_path("/srv/b", "part-1.csv"), "/srv/b/part-1.csv")

    def test_cache_does_not_cross_roots(self) -> None:
        self.assertEqual(join_path("/mnt/one", "shard.bin"), "/mnt/one/shard.bin")
        self.assertEqual(join_path("/mnt/two", "shard.bin"), "/mnt/two/shard.bin")

    def test_trailing_slashes_per_root(self) -> None:
        self.assertEqual(join_path("/srv/x/", "tail.log"), "/srv/x/tail.log")
        self.assertEqual(join_path("/srv/y/", "tail.log"), "/srv/y/tail.log")

    def test_repeated_call_is_stable(self) -> None:
        first = join_path("/opt/app", "conf.ini")
        second = join_path("/opt/app", "conf.ini")
        self.assertEqual(first, "/opt/app/conf.ini")
        self.assertEqual(second, "/opt/app/conf.ini")

    def test_name_with_leading_slash(self) -> None:
        self.assertEqual(join_path("/opt/app", "/deep/file"), "/opt/app/deep/file")
        self.assertEqual(join_path("/other/app", "/deep/file"), "/other/app/deep/file")


if __name__ == "__main__":
    unittest.main()

