        float ripple = 0.5 + 0.5 * sin((vUv.y * 20.0 + uPhase) * 3.14159);
        colour *= 0.82 + 0.35 * ripple;
        gl_FragColor = vec4(colour, 1.0);
      }`,
  })
);
sea.name = 'sea';
sea.position.set(0, cameraY - half + seaHeight / 2, -distance);
scene.add(sea);

