  new THREE.CircleGeometry(SUN_R * 2 * half, 48),
  new THREE.MeshBasicMaterial({color: 0xffd08a})
);
sun.name = 'sun';
sun.scale.set(1.0, SUN_FLATTEN, 1.0);
const sunX = (0.478 - 0.5) * 2 * halfW;
const sunY = cameraY + half - 0.681 * 2 * half;
sun.position.set(sunX, sunY, -distance + 0.05);
scene.add(sun);

