outerRing.name = 'outer_ring';
outerRing.position.z = 0.12;
wheel.add(outerRing);

let t = 0;
const round = (v) => Math.round(v * 1e4) / 1e4;

window.__step = (dt) => {
  t += dt;
  wheel.rotation.z = OMEGA * t;
  renderer.render(scene, camera);
  return window.__probe();
};

window.__probe = () => ({
